def write_detail(name,title,desc,buttons):
    btns="".join([f'<Button android:id="@+id/btn{i}" android:layout_width="match_parent" android:layout_height="64dp" android:text="{b}" android:textColor="#FFFFFF" android:backgroundTint="#2ECC71" android:textSize="12sp" android:layout_marginTop="8dp"/>' for i,b in enumerate(buttons)])
    xml=f'''<?xml version="1.0" encoding="utf-8"?><ScrollView xmlns:android="http://schemas.android.com/apk/res/android" android:layout_width="match_parent" android:layout_height="match_parent" android:background="#FFFFFF"><LinearLayout android:orientation="vertical" android:layout_width="match_parent" android:layout_height="wrap_content" android:padding="14dp"><LinearLayout android:orientation="horizontal" android:layout_width="match_parent" android:layout_height="64dp" android:background="#2ECC71" android:gravity="center_vertical" android:padding="12dp"><Button android:id="@+id/btnBack" android:layout_width="52dp" android:layout_height="52dp" android:text="BACK" android:textColor="#FFFFFF" android:backgroundTint="#2ECC71" android:textSize="12sp"/><TextView android:layout_width="0dp" android:layout_weight="1" android:layout_height="wrap_content" android:text="{title}" android:textSize="17sp" android:textStyle="bold" android:textColor="#FFFFFF" android:gravity="center"/></LinearLayout><TextView android:layout_width="match_parent" android:layout_height="wrap_content" android:text="{desc}" android:textSize="12sp" android:textColor="#000000" android:layout_marginTop="14dp" android:background="#F5F5F5" android:padding="10dp"/><LinearLayout android:orientation="horizontal" android:layout_width="match_parent" android:layout_height="56dp" android:background="#F0F0F0" android:gravity="center_vertical" android:padding="10dp" android:layout_marginTop="12dp"><TextView android:id="@+id/txtFile" android:layout_width="0dp" android:layout_weight="1" android:layout_height="wrap_content" android:text="/sdcard/Download/" android:textSize="13sp" android:textColor="#000000"/><Button android:id="@+id/btnBrowse" android:layout_width="90dp" android:layout_height="44dp" android:text="BROWSE" android:textColor="#FFFFFF" android:backgroundTint="#2ECC71" android:textSize="11sp"/></LinearLayout><LinearLayout android:orientation="vertical" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="14dp">{btns}</LinearLayout><ProgressBar android:id="@+id/progressBar" style="?android:attr/progressBarStyleHorizontal" android:layout_width="match_parent" android:layout_height="16dp" android:max="100" android:progress="0" android:progressTint="#2ECC71" android:layout_marginTop="16dp"/><TextView android:id="@+id/txtDetail" android:layout_width="match_parent" android:layout_height="wrap_content" android:text="Ready {title}" android:textSize="12sp" android:textColor="#000000" android:layout_marginTop="6dp"/><TextView android:id="@+id/logView" android:layout_width="match_parent" android:layout_height="wrap_content" android:background="#111111" android:textColor="#00FF00" android:textSize="11sp" android:padding="10dp" android:layout_marginTop="10dp" android:text="LOG {title}"/></LinearLayout></ScrollView>'''
    open(f"app/src/main/res/layout/activity_{name}.xml","w").write(xml)

